#################################################################
#    Classes: Top-Level Taxonomy
#################################################################

ea:AssessmentEntity
    a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Assessment Entity"@en ;
    rdfs:comment "Root entity for all assessment domain elements."@en .

ea:Assessment
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEntity ;
    rdfs:label "Assessment"@en ;
    skos:altLabel "Educational Assessment"@en, "Educational Evaluation"@en ;
    rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude, and beliefs to refine programs and improve student learning."@en .

ea:AssessmentComponent
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEntity ;
    rdfs:label "Assessment Component"@en ;
    rdfs:comment "Structural items, questions, and parts forming assessments."@en .

ea:AssessmentEvaluationTool
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEntity ;
    rdfs:label "Assessment Evaluation Tool"@en ;
    rdfs:comment "Instruments, scoring guides, rubrics, and thresholds used to evaluate performance."@en .

ea:AssessmentProcessAttribute
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEntity ;
    rdfs:label "Assessment Process Attribute"@en ;
    rdfs:comment "Reified dimensions, axes, and characteristics classifying assessment practice."@en .

ea:CurricularEntity
