    rdfs:label "Educational Feedback"@en ;
    rdfs:comment "Information provided to learners to guide learning progress."@en .

ea:EducationalMeasurementEntity
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEntity ;
    rdfs:label "Educational Measurement Entity"@en ;
    rdfs:comment "Quantitative psychometric entities including scores, errors, and groups."@en .

ea:PsychometricQuality
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEntity ;
    rdfs:label "Psychometric Quality"@en ;
    rdfs:comment "Attributes of measurement precision and validity."@en .

#################################################################
#    Axis Reification: Purpose
#################################################################

ea:PurposeCategory
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentProcessAttribute ;
    rdfs:label "Purpose Category"@en ;
    owl:disjointUnionOf (
        ea:PlacementPurpose
        ea:FormativePurpose
        ea:SummativePurpose
        ea:DiagnosticPurpose
        ea:InterimPurpose
        ea:ScreeningPurpose
    ) .

ea:PlacementPurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Placement Purpose"@en ;
    skos:altLabel "Initial Purpose"@en, "Pre-Assessment Purpose"@en .

ea:FormativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Formative Purpose"@en ;
    skos:altLabel "Educative Purpose"@en, "Assessment for Learning Purpose"@en .

ea:SummativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Summative Purpose"@en ;
    skos:altLabel "Assessment of Learning Purpose"@en .

ea:DiagnosticPurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Diagnostic Purpose"@en .

ea:InterimPurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Interim Purpose"@en ;
    skos:altLabel "Benchmark Purpose"@en .

ea:ScreeningPurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Screening Purpose"@en .

ea:PlacementAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasPurpose ;
                owl:someValuesFrom ea:PlacementPurpose
            ]
        )
    ] ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en, "Pre-Assessment"@en, "Threshold Knowledge Test"@en .

ea:FormativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasPurpose ;
                owl:someValuesFrom ea:FormativePurpose
            ]
        )
    ] ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Assessment for Learning"@en, "Classroom Assessment"@en, "Educative Assessment"@en .

ea:SummativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
