                owl:someValuesFrom ea:SummativePurpose
            ]
        )
    ] ;
    rdfs:label "Summative Assessment"@en ;
    skos:altLabel "Assessment of Learning"@en, "Summative Evaluation"@en .

ea:DiagnosticAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment, ea:FormativeAssessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasPurpose ;
                owl:someValuesFrom ea:DiagnosticPurpose
            ]
        )
    ] ;
    rdfs:label "Diagnostic Assessment"@en ;
    skos:altLabel "Diagnostic Testing"@en ;
    rdfs:comment "Taxonomic tension: Passages 2 and 3 classify diagnostic assessment as a coordinate category alongside placement, formative, and summative assessments. However, Passages 4, 12, 14, and 15 explicitly subordinate diagnostic assessment under formative assessment ('A common form of formative assessment is diagnostic assessment'). Both claims are modeled as axioms."@en .

ea:InterimAssessment
    a owl:Class ;
