    skos:altLabel "Benchmark Assessment"@en, "Benchmark Test"@en ;
    rdfs:comment "The corpus notes debate over whether interim assessments are formative (used diagnostically to modify instruction) or summative (monitoring mastery towards end-of-course tests)."@en .

ea:ScreeningAssessment
    a owl:Class ;
